def build_details(values):
    data = dict(values)
    net, returned = data.get("sold_cost_of_goods"), data.get("returned_cost_of_goods")
    data["detail_gross_cost"] = round(net + returned, 2) if net is not None and returned is not None else None
    data["detail_hundred"] = 100
    result = {}
    for metric, (description, components) in SPECS.items():
        rows = [{"sign": sign, "label": label, "value": data.get(key)} for sign, label, key in components]
        available = bool(rows) and all(row["value"] is not None for row in rows)
        result[metric] = {
            "description": description, "rows": rows, "available": available,
            "note": "" if available or not rows else "За часть выбранных дней разбивка ещё не сохранена или не хватает исходных данных. Требуется пересчёт. Прочерк не означает ноль.",
        }
    return result
